import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Absent for users who only ever signed in via an OAuth provider (e.g. Google)
  // or via a magic link and never set one.
  passwordHash?: string;
  // Set once a magic-link (or OAuth) sign-in has confirmed the user controls this
  // address. Mirrors the Auth.js AdapterUser.emailVerified field.
  emailVerified?: string | null;
  // Bumped by "sign out of all devices". Embedded in every JWT at issue time;
  // the auth.ts `jwt` callback rejects any token whose version doesn't match
  // the live value, which is what makes revocation actually take effect.
  sessionVersion?: number;
};

// Next.js (Turbopack, in both dev and prod) can load this module more than once —
// route handlers and page renders don't always land in the same module instance.
// Pin the store on globalThis so every instance reads/writes the same array within
// this process; otherwise sign-ups made via /api/signup silently "vanish" when the
// dashboard re-reads users through a different copy of this module.
const globalForUsers = globalThis as unknown as { __notelyUsers?: User[] };

const users: User[] =
  globalForUsers.__notelyUsers ??
  (globalForUsers.__notelyUsers = [
    { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
    { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
  ]);

// Links an OAuth (or other adapter-mediated) account to a local user, e.g.
// { provider: "google", providerAccountId: "<google sub>" } -> userId.
// Same globalThis-pinning rationale as `users` above.
type AccountLink = { provider: string; providerAccountId: string; userId: string };
const globalForAccounts = globalThis as unknown as { __notelyAccounts?: AccountLink[] };
const accountLinks: AccountLink[] =
  globalForAccounts.__notelyAccounts ?? (globalForAccounts.__notelyAccounts = []);

// Pending magic-link tokens, keyed by (identifier, hashed token). Auth.js hashes
// the token before it ever reaches us, so we just store and match opaque strings.
type VerificationTokenRecord = { identifier: string; token: string; expires: string };
const globalForTokens = globalThis as unknown as {
  __notelyVerificationTokens?: VerificationTokenRecord[];
};
const verificationTokens: VerificationTokenRecord[] =
  globalForTokens.__notelyVerificationTokens ?? (globalForTokens.__notelyVerificationTokens = []);

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

function nextId(): string {
  return String(users.length + 1);
}

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

// Used by the credentials sign-up flow.
export async function createUser({
  email,
  name,
  password,
}: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  if (await getUserByEmail(email)) {
    throw new Error("A user with that email already exists");
  }
  const passwordHash = await bcrypt.hash(password, 10);
  const user: User = {
    id: nextId(),
    email,
    name,
    createdAt: today(),
    passwordHash,
  };
  users.push(user);
  return user;
}

// Used by the credentials sign-in flow. Returns the user only if the password matches.
export async function verifyPassword(
  email: string,
  password: string
): Promise<User | undefined> {
  const user = await getUserByEmail(email);
  if (!user?.passwordHash) return undefined;
  const valid = await bcrypt.compare(password, user.passwordHash);
  return valid ? user : undefined;
}

// Used by OAuth providers (e.g. Google) and by the magic-link adapter: find the
// existing account by email, or provision one on first sign-in. Users provisioned
// this way have no passwordHash, so they can't also be logged into via the
// credentials form until they set one from /account.
export async function findOrCreateOAuthUser({
  email,
  name,
}: {
  email: string;
  name: string;
}): Promise<User> {
  const existing = await getUserByEmail(email);
  if (existing) return existing;
  const user: User = { id: nextId(), email, name, createdAt: today() };
  users.push(user);
  return user;
}

export async function setEmailVerified(
  id: string,
  emailVerified: Date | null
): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  if (!user) return undefined;
  user.emailVerified = emailVerified ? emailVerified.toISOString() : null;
  return user;
}

// Account-linking table backing the Auth.js adapter (used by the Google provider).
export async function getUserByAccount({
  provider,
  providerAccountId,
}: {
  provider: string;
  providerAccountId: string;
}): Promise<User | undefined> {
  const link = accountLinks.find(
    (a) => a.provider === provider && a.providerAccountId === providerAccountId
  );
  if (!link) return undefined;
  return getUser(link.userId);
}

export async function linkAccount({
  provider,
  providerAccountId,
  userId,
}: {
  provider: string;
  providerAccountId: string;
  userId: string;
}): Promise<void> {
  const exists = accountLinks.some(
    (a) => a.provider === provider && a.providerAccountId === providerAccountId
  );
  if (!exists) accountLinks.push({ provider, providerAccountId, userId });
}

// Verification-token table backing the Auth.js adapter (used by the magic-link
// / Resend provider). Tokens are single-use: `consumeVerificationToken` removes
// the matching record so a link can't be replayed.
export async function createVerificationTokenRecord({
  identifier,
  token,
  expires,
}: {
  identifier: string;
  token: string;
  expires: Date;
}): Promise<void> {
  verificationTokens.push({ identifier, token, expires: expires.toISOString() });
}

export async function consumeVerificationToken({
  identifier,
  token,
}: {
  identifier?: string;
  token: string;
}): Promise<{ identifier: string; token: string; expires: Date } | undefined> {
  const idx = verificationTokens.findIndex(
    (t) => t.token === token && (!identifier || t.identifier === identifier)
  );
  if (idx === -1) return undefined;
  const [record] = verificationTokens.splice(idx, 1);
  return { identifier: record.identifier, token: record.token, expires: new Date(record.expires) };
}

// Sets (or replaces) a user's password. Used both by /account "change password"
// (when a current password is on file, it must be supplied and match) and to let
// OAuth/magic-link-only users add a password for the first time.
export async function changePassword(
  id: string,
  { currentPassword, newPassword }: { currentPassword?: string; newPassword: string }
): Promise<void> {
  const user = users.find((u) => u.id === id);
  if (!user) throw new Error("User not found.");
  if (newPassword.length < 8) {
    throw new Error("New password must be at least 8 characters.");
  }
  if (user.passwordHash) {
    if (!currentPassword || !(await bcrypt.compare(currentPassword, user.passwordHash))) {
      throw new Error("Current password is incorrect.");
    }
  }
  user.passwordHash = await bcrypt.hash(newPassword, 10);
}

// Permanently removes a user and any account links pointing at them.
export async function deleteUser(id: string): Promise<void> {
  const idx = users.findIndex((u) => u.id === id);
  if (idx === -1) return;
  users.splice(idx, 1);
  for (let i = accountLinks.length - 1; i >= 0; i--) {
    if (accountLinks[i].userId === id) accountLinks.splice(i, 1);
  }
}

// "Sign out of all devices": bumping this invalidates every JWT already issued
// for this user, since auth.ts's `jwt` callback rejects tokens whose embedded
// sessionVersion no longer matches.
export async function bumpSessionVersion(id: string): Promise<number> {
  const user = users.find((u) => u.id === id);
  if (!user) throw new Error("User not found.");
  user.sessionVersion = (user.sessionVersion ?? 0) + 1;
  return user.sessionVersion;
}

export async function getCurrentUser(): Promise<User | undefined> {
  // Imported lazily to avoid a module cycle: src/auth.ts imports from this file
  // (verifyPassword, findOrCreateOAuthUser) to implement its providers.
  const { auth } = await import("@/auth");
  const session = await auth();
  if (!session?.user?.email) return undefined;
  return getUserByEmail(session.user.email);
}

