"use client";

import { useState, type FormEvent } from "react";
import { signOut } from "next-auth/react";

export function AccountForm({ hasPassword }: { hasPassword: boolean }) {
  return (
    <div className="mt-8 space-y-10">
      <PasswordSection hasPassword={hasPassword} />
      <SignOutAllSection />
      <DeleteAccountSection />
    </div>
  );
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="space-y-3 rounded-xl border border-black/[.08] p-6 dark:border-white/[.145]">
      <h2 className="text-lg font-medium">{title}</h2>
      {children}
    </section>
  );
}

function PasswordSection({ hasPassword }: { hasPassword: boolean }) {
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setSuccess(false);
    setLoading(true);

    const res = await fetch("/api/account/password", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ currentPassword, newPassword }),
    });
    const data = await res.json().catch(() => ({}));
    setLoading(false);

    if (!res.ok) {
      setError(data.error ?? "Something went wrong.");
      return;
    }

    setCurrentPassword("");
    setNewPassword("");
    setSuccess(true);
  }

  return (
    <Section title={hasPassword ? "Change password" : "Set a password"}>
      {!hasPassword && (
        <p className="text-sm opacity-70">
          Your account doesn&apos;t have a password yet (you signed in with Google or a
          magic link). Set one to also be able to sign in with email and password.
        </p>
      )}
      <form onSubmit={handleSubmit} className="max-w-sm space-y-4">
        {hasPassword && (
          <div className="space-y-1">
            <label htmlFor="currentPassword" className="text-sm font-medium">
              Current password
            </label>
            <input
              id="currentPassword"
              type="password"
              required
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              className="w-full rounded-md border border-black/[.08] bg-transparent px-3 py-2 text-sm outline-none focus:border-black/40 dark:border-white/[.145] dark:focus:border-white/40"
            />
          </div>
        )}
        <div className="space-y-1">
          <label htmlFor="newPassword" className="text-sm font-medium">
            New password
          </label>
          <input
            id="newPassword"
            type="password"
            required
            minLength={8}
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            className="w-full rounded-md border border-black/[.08] bg-transparent px-3 py-2 text-sm outline-none focus:border-black/40 dark:border-white/[.145] dark:focus:border-white/40"
          />
          <p className="text-xs text-zinc-500">At least 8 characters.</p>
        </div>

        {error && <p className="text-sm text-red-600 dark:text-red-400">{error}</p>}
        {success && <p className="text-sm text-green-600 dark:text-green-400">Password updated.</p>}

        <button
          type="submit"
          disabled={loading}
