import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import Google from "next-auth/providers/google";
import Resend from "next-auth/providers/resend";
import { usersAdapter } from "@/lib/auth-adapter";
import { findOrCreateOAuthUser, getUser, verifyPassword } from "@/lib/users";

export const { handlers, signIn, signOut, auth } = NextAuth({
  // Only needed for the magic-link (Resend) provider's verification tokens and
  // to remember which Google account maps to which local user — see
  // src/lib/auth-adapter.ts. Sessions themselves stay JWT-based (below), not
  // database-based.
  adapter: usersAdapter,
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
      // We already treat "same email" as "same person" for Google sign-in
      // (findOrCreateOAuthUser below matches by email), so allow the adapter
      // to link a Google account to an existing password/magic-link account
      // with the same address instead of erroring out.
      allowDangerousEmailAccountLinking: true,
    }),
    Resend({
      apiKey: process.env.AUTH_RESEND_KEY,
      from: process.env.EMAIL_FROM,
    }),
    Credentials({
      name: "Email and password",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      authorize: async (credentials) => {
        const email = credentials?.email;
        const password = credentials?.password;
        if (typeof email !== "string" || typeof password !== "string") return null;

        const user = await verifyPassword(email, password);
        if (!user) return null;

        return { id: user.id, email: user.email, name: user.name };
      },
    }),
  ],
  session: { strategy: "jwt" },
  pages: {
    signIn: "/signin",
    verifyRequest: "/verify-request",
  },
  callbacks: {
    async signIn({ user, account }) {
      // Provision (or link to) a local user record on first Google sign-in.
      if (account?.provider === "google" && user.email) {
        await findOrCreateOAuthUser({
          email: user.email,
          name: user.name ?? user.email,
        });
      }
      return true;
    },
    async jwt({ token, user }) {
      if (user) {
        // Fresh sign-in (any provider). Stamp the token with the user's id and
        // their current sessionVersion so later requests can be checked against
        // the live record below.
        token.uid = user.id;
        const dbUser = await getUser(user.id);
        token.sessionVersion = dbUser?.sessionVersion ?? 0;
        return token;
      }

      // Every subsequent request: re-check against the live user record. This
      // is what makes account deletion and "sign out of all devices" take
      // effect immediately instead of waiting for the JWT to expire — a
      // missing user or a stale sessionVersion invalidates the token.
      if (typeof token.uid !== "string") return token;
      const dbUser = await getUser(token.uid);
      if (!dbUser || (dbUser.sessionVersion ?? 0) !== (token.sessionVersion ?? 0)) {
        return null;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user && typeof token.uid === "string") {
        session.user.id = token.uid;
      }
      return session;
    },
  },
});
